import json
import os
import sys
import time
from typing import Any, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _get_env(name: str, default: Optional[str] = None) -> str:
    value = os.getenv(name, default)
    if value is None or value == "":
        raise ValueError(f"Missing required environment variable: {name}")
    return value


def _json_default(obj: Any) -> Any:
    return str(obj)


def send_failed_message_to_dead_letter(
    failed_message: Any,
    dead_letter_queue_url: Optional[str] = None,
    source_message_id: Optional[str] = None,
    error: Optional[Exception] = None,
) -> dict:
    sqs = boto3.client("sqs")

    queue_url = dead_letter_queue_url or _get_env("AWS_SQS_DEAD_LETTER_QUEUE_URL")
    payload = {
        "failed_message": failed_message,
        "source_message_id": source_message_id,
        "error": None if error is None else str(error),
        "timestamp": int(time.time()),
    }

    try:
        response = sqs.send_message(
            QueueUrl=queue_url,
            MessageBody=json.dumps(payload, default=_json_default),
        )
        return {
            "ok": True,
            "message_id": response.get("MessageId"),
            "md5_of_message_body": response.get("MD5OfMessageBody"),
        }
    except (BotoCoreError, ClientError) as exc:
        return {
            "ok": False,
            "error": str(exc),
        }


def handle_message_and_dead_letter(
    message_body: Any,
    process_fn,
    dead_letter_queue_url: Optional[str] = None,
    source_message_id: Optional[str] = None,
) -> dict:
    try:
        result = process_fn(message_body)
        return {"ok": True, "result": result}
    except Exception as exc:
        return send_failed_message_to_dead_letter(
            failed_message=message_body,
            dead_letter_queue_url=dead_letter_queue_url,
            source_message_id=source_message_id,
            error=exc,
        )


if __name__ == "__main__":
    def _example_processor(payload: Any) -> Any:
        if isinstance(payload, dict) and payload.get("fail"):
            raise RuntimeError("processing failed")
        return {"processed": True, "input": payload}

    if len(sys.argv) > 1:
        raw = sys.argv[1]
        try:
            message = json.loads(raw)
        except json.JSONDecodeError:
            message = raw
    else:
        message = {"fail": True, "example": "message"}

    output = handle_message_and_dead_letter(message, _example_processor)
    print(json.dumps(output))
